'use strict';
const jwtDecode = require('jwt-decode');
const passportUtils = require('../passport/utils');
const pathUtil = require('../utils/path-util');
const headerUtils = require('../utils/header-util');
const loggerUtil = require('../utils/logger');
const vcapUtils = require('../utils/vcap-utils');
const basicAuth = require('basic-auth');
const tokenUtils = require('../utils/token-utils');
const cookieUtils = require('../utils/cookie-utils');
const {writeAuditLog} = require('../utils/audit-log');
const {getTenantFromToken} = require('../utils/tenant-utils');
const iasUtils = require('../utils/ias-utils');
const {verifyExtSessionIdSignature} = require('../utils/ext-session-utils');
const logger = loggerUtil.getLogger('/service2approuter-middleware');

module.exports = async function (req, res, next) {
  let auth = req.headers && req.headers['x-approuter-authorization'];
  if (!auth) {
    return next();
  }
  const tracer = req.loggingContext.getTracer(__filename);
  tracer.debug('Incoming request contains x-approuter-authorization header');

  if (req.routerConfig && pathUtil.isPublicPath(req)) {
    tracer.debug('Request to public route with url %s contains x-approuter-authorization header ', req.url);
  }
  if (req.headers['x-approuter-authorization'].startsWith('Basic')){
    const ownCredentials = getStartupCredentials(req, 'xsuaa');
    if (!ownCredentials) {
      return next('No XSUAA service instance bound for x-approuter-authorization');
    }
    const creds = basicAuth({headers: {authorization: req.headers['x-approuter-authorization']}});
    if (!creds){
      return writeAuditLog(req, null , `Invalid x-approuter-authorization header for request url ${req.url}`, 401, null, ownCredentials, next);
    }
    try {
      const tenant = req.tenant || getTenantFromToken(req,null,ownCredentials);
      const tokenResponse = await tokenUtils.getPasswordUserToken(tenant, creds, ownCredentials, headerUtils.getCorrelationId(req));
      if (req.requiredRoleCollection && (!tokenResponse.tokenDecoded.roleCollections ||
          !tokenResponse.tokenDecoded.roleCollections.includes(req.requiredRoleCollection))){
        const tokenKey = tenant + creds.name + creds.pass;
        tokenUtils.deleteTokenCache(tokenKey);
        return writeAuditLog(req, creds.name , `Setting log level failed for request url ${req.url} because the required role collection ${req.requiredRoleCollection} is missing`, 403, creds.name, ownCredentials, next);
      }
      req.headers['x-approuter-authorization'] = `Bearer ${tokenResponse.accessToken}`;
      return handleSession(req,tokenResponse.tokenDecoded, tokenResponse.accessToken,tracer,{credentials:ownCredentials},res, next);
    } catch (err){
      return writeAuditLog(req, creds.name , `${err.message} - Token validation failed for request url ${req.url}`, 401, creds.name, ownCredentials, next);
    }
  }
  else {
    let tokenDecoded;
    try {
      tokenDecoded = jwtDecode(auth);
    } catch (err) {
      let error = new Error('Failed to decode x-approuter-authorization token ' + err);
      error.status = 400;
      return next(error);
    }

    const authArr = auth.split(' ');
    const type = authArr[0];
    const tokenValue = authArr[1];
    let service = getCredentialsAndSecurityType(tokenDecoded, req);
    if (!service.credentials) {
      return next('No Security service instance bound for service type ' + service.type);
    }

    if (tokenDecoded.app_tid) {
      if (!service.credentials['btp-tenant-api']) {
        return next('Missing btp-tenant-api configuration in service credentials');
      }
      try {
        req.iasSubdomain = await iasUtils.getSubdomainByApptid(tokenDecoded.app_tid,service.credentials['btp-tenant-api']);
      }
      catch (err){
        return next('Failed to fetch subdomain by app_tid ' + err.message);
      }
    }

    if (type.toLowerCase() !== 'bearer') {
      return writeAuditLog(req, tokenValue, 'x-approuter-authorization header is not a Bearer token', 400, tokenDecoded, service.credentials, next);
    }

    const config = {
      credentials: service.credentials,
      correlationId: headerUtils.getCorrelationId(req)
    };
    try {
      await tokenUtils.checkSecurityContext(tokenValue,config);
      return handleSession(req, tokenDecoded, tokenValue, tracer, service, res, next);
    } catch (err) {
      writeAuditLog(req, tokenValue, `${err.message} - Token validation failed for request url ${req.url}`, 401, tokenDecoded, service.credentials, next);
    }
  }
};

function getStartupCredentials(req, type) {
  const routerConfig = req && req.routerConfig;
  let source;
  if (type === 'xsuaa') {
    const options = routerConfig && routerConfig.uaaConfig && routerConfig.uaaConfig.options;
    if (options && Object.keys(options).length > 0) {
      source = options;
    } else {
      source = vcapUtils.getServiceCredentials({tag: 'xsuaa'});
      if (source && process.env.XSUAA_PRIVATE_KEY) {
        source = Object.assign({}, source, {key: process.env.XSUAA_PRIVATE_KEY});
      }
    }
  } else {
    const options = routerConfig && routerConfig.iasConfig && routerConfig.iasConfig.options;
    if (options && Object.keys(options).length > 0) {
      source = options;
    } else {
      source = vcapUtils.getServiceCredentials({label: 'identity'});
      if (source && process.env.IAS_PRIVATE_KEY) {
        source = Object.assign({}, source, {key: process.env.IAS_PRIVATE_KEY});
      }
    }
  }
  if (source) {
    const credentials = Object.assign({}, source);
    credentials.label = type === 'xsuaa' ? 'xsuaa' : 'identity';
    return credentials;
  } else {
    return null;
  }
}

function getCredentialsAndSecurityType(tokenDecoded, req) {
  let service = {};
  if (tokenDecoded && tokenDecoded.ext_attr) {
    service.credentials = getStartupCredentials(req, 'xsuaa');
    service.type = 'XSUAA';
  } else {
    service.credentials = getStartupCredentials(req, 'ias');
    service.type = 'IAS';
  }
  return service;
}

async function handleSession(req, tokenDecoded, tokenValue, tracer, service, res, next) {
  const externalSessionStore = req && req.app && req.app.get('externalSessionStore');
  const tenant = req.tenant || getTenantFromToken(req, tokenDecoded, service.credentials);
  const routerConfig = req && req.routerConfig;

  const externalSessionContext = getExternalSessionContext(req, tokenDecoded, externalSessionStore, routerConfig, next);
  if (externalSessionContext.failed) {
    return externalSessionContext.result;
  }

  if (!verifyExternalSessionSignature(req, tokenDecoded, tokenValue, service, externalSessionContext, routerConfig, next)) {
    return;
  }

  let externalSession = null;
  if (externalSessionStore) {
    externalSession = await externalSessionStore.getExternalSession(externalSessionContext.id, req);
  }

  const externalSessionUpdate = setSession(req, res, {
    tokenDecoded, tokenValue, service, tenant, externalSession, externalSessionStore, externalSessionContext, routerConfig
  });

  if (externalSessionStore && externalSessionUpdate) {
    await externalSessionStore.updateExternalSession(req.session);
  }
  tracer.info('Session created successfully');
  return next();
}

function getExternalSessionContext(req, tokenDecoded, externalSessionStore, routerConfig, next) {
  const providedId = req.headers['x-approuter-ext-session-id'];
  if (!externalSessionStore || !providedId) {
    return {id: tokenDecoded.jti, expiry: tokenDecoded.exp, providedId: undefined};
  }

  const secret = routerConfig && routerConfig.svc2arExternalSessionIdSecret;
  const signature = req.headers['x-approuter-ext-session-id-sig'];
  if (!signature && secret) {
    return {failed: true, result: next(Object.assign(new Error('x-approuter-ext-session-id-sig is missing'), {status: 400}))};
  }
  if (!req.headers['x-approuter-ext-session-expiry']) {
    return {failed: true, result: next(Object.assign(new Error('x-approuter-ext-session-expiry is missing'), {status: 400}))};
  }

  const expiry = parseInt(req.headers['x-approuter-ext-session-expiry']);
  if (Number.isNaN(expiry)) {
    return {failed: true, result: next(Object.assign(new Error('x-approuter-ext-session-expiry should be a number'), {status: 400}))};
  }
  if (expiry <= Math.floor(Date.now() / 1000)) {
    return {failed: true, result: next(Object.assign(new Error('x-approuter-ext-session-expiry should be a timestamp in the future'), {status: 400}))};
  }

  delete req.headers['x-approuter-ext-session-id'];
  delete req.headers['x-approuter-ext-session-expiry'];
  delete req.headers['x-approuter-ext-session-id-sig'];

  return {id: providedId, expiry, providedId, signature};
}

function verifyExternalSessionSignature(req, tokenDecoded, tokenValue, service, externalSessionContext, routerConfig, next) {
  if (!externalSessionContext.providedId) {
    return true;
  }
  const secret = routerConfig && routerConfig.svc2arExternalSessionIdSecret;
  if (!secret) {
    return true;
  }
  try {
    if (!verifyExtSessionIdSignature(externalSessionContext.id, externalSessionContext.signature,
      secret,
      routerConfig && routerConfig.svc2arExternalSessionIdSecretAlt)) {
      writeAuditLog(req, tokenValue, `external session id signature verification failed for request url ${req.url}, x-approuter-ext-session-id ${externalSessionContext.id}, x-approuter-ext-session-signature: ${externalSessionContext.signature}`, 401, tokenDecoded, service.credentials, next);
      return false;
    }
  } catch (e) {
    next(e);
    return false;
  }
  return true;
}

function setSession(req, res, {tokenDecoded, tokenValue, service, tenant, externalSession, externalSessionStore,
  externalSessionContext, routerConfig}) {
  if (externalSession) {
    return updateSession(req, tokenDecoded, tokenValue, service, tenant, externalSession, externalSessionContext.expiry);
  }
  req.session = createSession(req, tokenDecoded, tokenValue, service, tenant, externalSessionStore, externalSessionContext);
  if (routerConfig && routerConfig.svc2arExternalSessionCookieEnabled) {
    res && externalSessionContext.providedId && cookieUtils.addSessionCookie(req, res);
  }
  return true;
}

function updateSession(req, tokenDecoded, tokenValue, service, tenant, externalSession, externalSessionExpiry) {
  let externalSessionUpdate = false;
  req.session = externalSession;
  if (req.session.user.token.accessToken !== tokenValue) {
    req.session.user = passportUtils.getUserProperties(getTokenContext(tokenValue, tokenDecoded, service.credentials, service.type, tenant));
    externalSessionUpdate = true;
  }
  if (req.session.externalSessionExpiration !== externalSessionExpiry) {
    req.session.externalSessionExpiration = externalSessionExpiry;
    externalSessionUpdate = true;
  }
  return externalSessionUpdate;
}

function createSession(req, tokenDecoded, tokenValue, service, tenant, externalSessionStore, externalSessionContext) {
  return {
    externalSessionId: externalSessionStore && externalSessionContext.id,
    externalSessionExpiration: externalSessionStore && externalSessionContext.expiry,
    jwtRefreshStarted: true,
    user: passportUtils.getUserProperties(getTokenContext(tokenValue, tokenDecoded, service.credentials, service.type, tenant)),
    req: req,
    reload: function (cb) {
      cb();
    },
    save: function (cb) {
      cb && cb();
    },
    touch: function () {
    }
  };
}

function getTokenContext(tokenValue, tokenDecoded, credentials, authenticationType, tenant) {
  const tokenContext = {
    expiresIn: Date.now() + 600000,
    scope: tokenDecoded.scope,
    oauthOptions: credentials,
    urlTenant: tenant
  };
  if (authenticationType === 'IAS'){
    tokenContext.accessToken = tokenContext.idToken  = tokenValue;
    tokenContext.oauthOptions.authenticationType = 'ias';
    tokenDecoded.ias_iss && (tokenContext.oauthOptions.url = tokenDecoded.ias_iss);
  }
  else {
    tokenContext.accessToken  = tokenValue;
    tokenContext.oauthOptions.authenticationType = 'xsuaa';
  }
  logger.info(`Token context in service 2 approuter is tenant ${tenant}, authenticationType ${authenticationType}`);
  return tokenContext;
}

// Export private functions for testing
module.exports._private = {
  getCredentialsAndSecurityType,
  handleSession,
  getExternalSessionContext,
  verifyExternalSessionSignature,
  setSession,
  updateSession,
  createSession
};
